/// The bytes of `scratch` that `vg_mlkem1024_decaps_avx2` may write: it changes no byte of `scratch` at this offset or beyond (`Artifact.written`).
pub const VG_MLKEM1024_DECAPS_AVX2_SCRATCH_WRITTEN: usize = 37376;

